using System.Collections.Generic;
using UnityEngine;

namespace NihongoLife.Core
{
    /// <summary>
    /// English -> Russian interface strings (Resources/Content/Localization/ru_table.json, generated by tools/content/build_ru.py).
    /// The key is the exact English string given to Loc.T. A missing key falls back to the English text (never Vietnamese
    /// unless English is empty). Loaded lazily the first time Russian is used.
    /// </summary>
    public static class RuTable
    {
        [System.Serializable] private class Pair { public string en; public string ru; }
        [System.Serializable] private class Dto { public string language; public int count; public List<Pair> entries = new List<Pair>(); }

        private static Dictionary<string, string> _map;

        public static int Count { get { Ensure(); return _map.Count; } }

        public static bool TryGet(string en, out string ru)
        {
            Ensure();
            ru = null;
            return en != null && _map.TryGetValue(en, out ru) && !string.IsNullOrEmpty(ru);
        }

        public static string Translate(string en, string fallbackVi)
        {
            if (TryGet(en, out string ru)) return ru;
            if (!string.IsNullOrEmpty(en) && _misses.Count < MaxMisses && HasLetters(en)) _misses.Add(en);
            return !string.IsNullOrEmpty(en) ? en : fallbackVi ?? "";
        }

        private const int MaxMisses = 6000;
        private static readonly HashSet<string> _misses = new HashSet<string>();

        /// <summary>English strings asked for in Russian that have no Russian line (a to-do list for the table; tests dump it).</summary>
        public static IReadOnlyCollection<string> Misses => _misses;
        public static void ClearMisses() => _misses.Clear();

        private static bool HasLetters(string s)
        {
            for (int i = 0; i < s.Length; i++) if ((s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= 'a' && s[i] <= 'z')) return true;
            return false;
        }

        public static void Reload() { _map = null; }

        private static void Ensure()
        {
            if (_map != null) return;
            _map = new Dictionary<string, string>();
            // ru_table = generated by build_ru.py; ru_table_extra = hand-written strings found by the coverage audit (wins on conflict).
            foreach (var path in new[] { "Content/Localization/ru_table", "Content/Localization/ru_table_extra" })
            {
                var asset = Resources.Load<TextAsset>(path);
                if (asset == null) { Debug.LogWarning("RuTable: " + path + " not found"); continue; }
                var dto = JsonUtility.FromJson<Dto>(asset.text);
                if (dto == null || dto.entries == null) continue;
                foreach (var pair in dto.entries)
                    if (pair != null && !string.IsNullOrEmpty(pair.en)) _map[pair.en] = pair.ru;
            }
        }
    }
}
